head.b:skin:
/*----------------------------------------------
  গলাচিপাপ্রতিদিন - Blogger Theme v2
  Modern Bengali news portal with unique layouts
----------------------------------------------*/

/* === CSS Variables === */
:root {
  --primary: #e11d48;
  --primary-light: #fce7f3;
  --foreground: #0a0a0b;
  --background: #fafafa;
  --card: #ffffff;
  --muted: #71717a;
  --border: #e4e4e7;
  --radius: 6px;
  --shadow-card: 0 1px 3px rgba(0,0,0,0.05), 0 1px 2px rgba(0,0,0,0.1);
  --shadow-hover: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.06);
  --container-width: 1200px;
  --blue: #1d4ed8;
  --purple: #9333ea;
  --green: #059669;
  --cyan: #0891b2;
  --amber: #b45309;
  --red: #dc2626;
  --health-green: #16a34a;
  --indigo: #7c3aed;
  --opinion: #d97706;
  --politics: #991b1b;
  --politics-light: #fef2f2;
  --politics-border: #fecaca;
  --trending: #ea580c;
  --trending-light: #fff7ed;
  --trending-border: #fed7aa;
}

/* === Reset & Base === */
* { margin: 0; padding: 0; box-sizing: border-box; border-color: var(--border); }

body {
  font-family: 'Hind Siliguri', sans-serif;
  background: var(--background);
  color: var(--foreground);
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; transition: color 0.2s; }
img { max-width: 100%; height: auto; display: block; }
h1, h2, h3, h4, h5, h6 { font-weight: 700; letter-spacing: -0.02em; line-height: 1.2; }

.container { max-width: var(--container-width); margin: 0 auto; padding: 0 1rem; }

/* === Top Bar === */
.top-bar { background: var(--foreground); padding: 6px 0; }
.top-bar .container { display: flex; justify-content: space-between; align-items: center; }
.top-bar span, .top-bar a { font-size: 12px; color: rgba(255,255,255,0.7); }
.top-bar a:hover { color: #fff; }

/* === Header / Logo === */
.site-logo-area { padding: 1rem 0; text-align: center; border-bottom: 1px solid var(--border); background: var(--card); }
.site-title { font-size: 2rem; font-weight: 700; color: var(--foreground); display: inline-block; }
.site-title .accent { color: var(--primary); }
.site-tagline { font-size: 12px; color: var(--muted); margin-top: 2px; }

/* === Navigation === */
.main-nav { background: var(--card); border-bottom: 1px solid var(--border); position: relative; }
.main-nav .container { display: flex; align-items: center; justify-content: space-between; }
.nav-list { display: flex; list-style: none; flex-wrap: wrap; }
.nav-list li a { display: block; padding: 10px 14px; font-size: 14px; font-weight: 500; color: rgba(10,10,11,0.8); transition: color 0.2s; white-space: nowrap; }
.nav-list li a:hover, .nav-list li a.active { color: var(--primary); }
.nav-list li:first-child a { font-weight: 600; color: var(--foreground); }
.nav-search { padding: 8px; color: var(--muted); cursor: pointer; background: none; border: none; font-size: 18px; }
.mobile-menu-btn { display: none; padding: 8px; background: none; border: none; font-size: 20px; color: var(--foreground); cursor: pointer; }

/* === Search Widget === */
.search-widget { display: none; background: var(--card); border-bottom: 1px solid var(--border); padding: 12px 0; }
.search-widget.active { display: block; }
.search-widget .container { display: flex; gap: 8px; }
.search-widget input { flex: 1; padding: 8px 14px; border: 1px solid var(--border); border-radius: var(--radius); font-size: 14px; font-family: inherit; outline: none; }
.search-widget input:focus { border-color: var(--primary); }
.search-widget button { background: var(--primary); color: #fff; border: none; padding: 8px 16px; border-radius: var(--radius); font-size: 14px; font-family: inherit; font-weight: 600; cursor: pointer; }

/* === Breaking News Ticker === */
.breaking-ticker { background: var(--card); border-bottom: 1px solid var(--border); overflow: hidden; }
.breaking-ticker .container { display: flex; align-items: center; gap: 12px; padding-top: 8px; padding-bottom: 8px; }
.breaking-label { background: var(--primary); color: #fff; padding: 4px 12px; font-size: 12px; font-weight: 700; border-radius: var(--radius); white-space: nowrap; flex-shrink: 0; }
.ticker-content { overflow: hidden; white-space: nowrap; flex: 1; }
.ticker-content .ticker-inner { display: inline-block; animation: ticker 30s linear infinite; }
.ticker-content .ticker-inner a { font-size: 13px; font-weight: 500; padding: 0 24px; color: var(--foreground); }
.ticker-content .ticker-inner a:hover { color: var(--primary); }
@keyframes ticker { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }

/* === Label Badge === */
.label-badge { display: inline-block; background: var(--primary-light); color: var(--primary); padding: 2px 8px; border-radius: 2px; font-size: 11px; font-weight: 700; }
.label-badge-overlay { position: absolute; top: 12px; left: 12px; background: var(--primary); color: #fff; padding: 4px 12px; border-radius: 4px; font-size: 11px; font-weight: 700; z-index: 2; }
.label-badge-bottom { position: absolute; bottom: 6px; left: 6px; background: rgba(0,0,0,0.7); color: #fff; padding: 2px 8px; border-radius: 3px; font-size: 10px; font-weight: 600; z-index: 2; }

/* === Section Header (reusable) === */
.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; padding-bottom: 8px; border-bottom: 2px solid var(--primary); }
.section-header .left { display: flex; align-items: center; gap: 8px; }
.section-header .dot { width: 12px; height: 12px; background: var(--primary); border-radius: 2px; flex-shrink: 0; }
.section-header h2 { font-size: 1.25rem; color: var(--foreground); }
.section-header .more-link { font-size: 13px; color: var(--primary); font-weight: 600; }
.section-header .more-link:hover { text-decoration: underline; }

/* Color-coded section headers */
.section-header.blue { border-bottom-color: var(--blue); }
.section-header.blue .dot { background: var(--blue); }
.section-header.purple { border-bottom-color: var(--purple); }
.section-header.purple .dot { background: var(--purple); }
.section-header.green { border-bottom-color: var(--green); }
.section-header.green .dot { background: var(--green); }
.section-header.cyan { border-bottom-color: var(--cyan); }
.section-header.cyan .dot { background: var(--cyan); }
.section-header.amber { border-bottom-color: var(--amber); }
.section-header.amber .dot { background: var(--amber); }
.section-header.red { border-bottom-color: var(--red); }
.section-header.red .dot { background: var(--red); }
.section-header.health { border-bottom-color: var(--health-green); }
.section-header.health .dot { background: var(--health-green); }
.section-header.indigo { border-bottom-color: var(--indigo); }
.section-header.indigo .dot { background: var(--indigo); }
.section-header.opinion { border-bottom-color: var(--opinion); }
.section-header.opinion .dot { background: var(--opinion); }
.section-header.politics { border-bottom-color: var(--politics); }
.section-header.politics .dot { background: var(--politics); }
.section-header.trending { border-bottom-color: var(--trending); }
.section-header.trending .dot { background: var(--trending); }

/* === রাজনীতি (Parliament/Debate Style) === */
.politics-section { margin-bottom: 32px; }
.politics-wrap { background: linear-gradient(135deg, var(--politics-light), #fee2e2); border-radius: 12px; padding: 20px; border: 1px solid var(--politics-border); }
.politics-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.politics-featured { position: relative; border-radius: 10px; overflow: hidden; background: var(--card); box-shadow: 0 4px 16px rgba(153,27,27,0.1); }
.politics-featured .thumb { position: relative; }
.politics-featured .thumb img { width: 100%; aspect-ratio: 16/9; object-fit: cover; }
.politics-featured .thumb-overlay { position: absolute; top: 0; left: 0; right: 0; background: linear-gradient(to bottom, rgba(153,27,27,0.8), transparent); padding: 10px 14px; }
.politics-featured .pol-badge { background: #fff; color: var(--politics); padding: 3px 10px; border-radius: 20px; font-size: 10px; font-weight: 800; letter-spacing: 1px; }
.politics-featured .info { padding: 16px; }
.politics-featured h3 { font-size: 18px; line-height: 1.3; }
.politics-featured p { font-size: 13px; color: var(--muted); margin-top: 8px; line-height: 1.5; }
.politics-featured .author-row { display: flex; align-items: center; gap: 8px; margin-top: 10px; }
.politics-featured .author-avatar { width: 24px; height: 24px; border-radius: 50%; background: var(--politics); color: #fff; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 700; }
.politics-featured .author-name { font-size: 12px; color: var(--politics); font-weight: 600; }
.politics-list { display: flex; flex-direction: column; }
.politics-item { display: flex; gap: 12px; padding: 14px 12px; border-bottom: 1px solid var(--politics-border); border-radius: 6px; transition: background 0.2s; }
.politics-item:nth-child(odd) { background: rgba(255,255,255,0.6); }
.politics-item:hover { background: rgba(255,255,255,0.9); }
.politics-item .num { flex-shrink: 0; width: 32px; height: 32px; border-radius: 50%; background: var(--politics); color: #fff; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 800; }
.politics-item h4 { font-size: 14px; line-height: 1.35; }
.politics-item .meta { display: flex; align-items: center; gap: 6px; margin-top: 6px; }
.politics-item .meta .author { font-size: 11px; color: var(--politics); font-weight: 600; }
.politics-item .meta .date { font-size: 11px; color: #a1a1aa; }

/* === আলোচিত (Trending/Viral Style) === */
.trending-section { margin-bottom: 32px; }
.trending-header { display: flex; align-items: center; justify-content: space-between; padding-bottom: 8px; border-bottom: 2px solid var(--trending); margin-bottom: 16px; }
.trending-header .left { display: flex; align-items: center; gap: 8px; }
.trending-header .fire { font-size: 20px; }
.trending-header h2 { font-size: 1.25rem; font-weight: 700; }
.trending-badge { background: var(--trending); color: #fff; padding: 2px 10px; border-radius: 20px; font-size: 10px; font-weight: 700; }
.trending-grid { display: grid; grid-template-columns: 2fr 1fr; gap: 16px; }
.trending-featured { position: relative; border-radius: 12px; overflow: hidden; }
.trending-featured img { width: 100%; aspect-ratio: 16/9; object-fit: cover; }
.trending-featured .overlay { position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.95) 0%, rgba(0,0,0,0.3) 50%, transparent); }
.trending-featured .badges { position: absolute; top: 12px; left: 12px; display: flex; gap: 8px; z-index: 2; }
.trending-featured .t-badge { background: var(--trending); color: #fff; padding: 4px 12px; border-radius: 20px; font-size: 11px; font-weight: 700; }
.trending-featured .view-badge { background: rgba(255,255,255,0.2); backdrop-filter: blur(4px); color: #fff; padding: 4px 10px; border-radius: 20px; font-size: 11px; font-weight: 600; }
.trending-featured .content { position: absolute; bottom: 0; left: 0; right: 0; padding: 24px 20px; z-index: 2; }
.trending-featured h3 { font-size: 22px; font-weight: 800; color: #fff; line-height: 1.25; text-shadow: 0 2px 4px rgba(0,0,0,0.5); }
.trending-featured p { font-size: 13px; color: rgba(255,255,255,0.75); margin-top: 8px; }
.trending-side { display: flex; flex-direction: column; gap: 12px; }
.trending-card { background: #fff; border-radius: 10px; overflow: hidden; border: 1px solid var(--trending-border); box-shadow: 0 2px 8px rgba(234,88,12,0.08); transition: box-shadow 0.2s; }
.trending-card:hover { box-shadow: 0 4px 16px rgba(234,88,12,0.15); }
.trending-card .inner { display: flex; gap: 10px; padding: 10px; }
.trending-card .thumb { position: relative; flex-shrink: 0; width: 70px; height: 56px; border-radius: 8px; overflow: hidden; }
.trending-card .thumb img { width: 100%; height: 100%; object-fit: cover; }
.trending-card .rank { position: absolute; top: 2px; left: 2px; background: var(--trending); color: #fff; width: 18px; height: 18px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 800; }
.trending-card h4 { font-size: 13px; font-weight: 700; line-height: 1.3; }
.trending-card .fire-date { display: flex; align-items: center; gap: 4px; margin-top: 4px; font-size: 10px; color: #a1a1aa; }
.trending-card .fire-date .fire { font-size: 10px; color: var(--trending); }

/* === শীর্ষ সংবাদ (Top News) === */
.top-news { padding: 20px 0; }
.top-news-grid { display: grid; grid-template-columns: 7fr 5fr; gap: 20px; }
.top-news-main { position: relative; }
.top-news-main .thumb { overflow: hidden; border-radius: 8px; position: relative; }
.top-news-main .thumb img { width: 100%; aspect-ratio: 16/10; object-fit: cover; transition: transform 0.5s; }
.top-news-main:hover .thumb img { transform: scale(1.02); }
.top-news-main .info { margin-top: 12px; }
.top-news-main .info h2 { font-size: 1.5rem; margin-top: 8px; transition: color 0.2s; }
.top-news-main:hover .info h2 { color: var(--primary); }
.top-news-main .info p { font-size: 14px; color: var(--muted); margin-top: 8px; }
.top-news-side { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.top-news-side-card { position: relative; }
.top-news-side-card .thumb { overflow: hidden; border-radius: 6px; position: relative; }
.top-news-side-card .thumb img { width: 100%; aspect-ratio: 16/10; object-fit: cover; transition: transform 0.3s; }
.top-news-side-card:hover .thumb img { transform: scale(1.02); }
.top-news-side-card h3 { font-size: 14px; margin-top: 6px; line-height: 1.35; transition: color 0.2s; }
.top-news-side-card:hover h3 { color: var(--primary); }
.top-news-side-card .date { font-size: 12px; color: var(--muted); margin-top: 4px; }

/* === জাতীয় (Timeline Style) === */
.national-section { margin-bottom: 32px; }
.national-grid { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; }
.national-featured { border-radius: 10px; overflow: hidden; background: var(--card); }
.national-featured img { width: 100%; aspect-ratio: 16/9; object-fit: cover; }
.national-featured .info { padding: 16px; }
.national-featured .info .label-badge { background: var(--blue); color: #fff; border-radius: 4px; padding: 3px 10px; }
.national-featured .info h3 { font-size: 18px; margin-top: 8px; line-height: 1.3; }
.national-featured .info p { font-size: 13px; color: var(--muted); margin-top: 6px; }
.timeline-list { display: flex; flex-direction: column; }
.timeline-item { display: flex; gap: 10px; padding: 12px 0; border-bottom: 1px solid var(--border); }
.timeline-dot-wrap { display: flex; flex-direction: column; align-items: center; flex-shrink: 0; width: 16px; }
.timeline-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--blue); border: 2px solid #dbeafe; margin-top: 4px; }
.timeline-line { width: 2px; flex: 1; background: #dbeafe; margin-top: 4px; }
.timeline-item h4 { font-size: 13px; font-weight: 600; line-height: 1.3; }
.timeline-item .date { font-size: 11px; color: var(--muted); display: block; margin-top: 4px; }

/* === বিনোদন (Cinema Reel Style) === */
.entertainment-section { margin-bottom: 32px; }
.entertainment-wrap { background: linear-gradient(135deg, #faf5ff, #f3e8ff); border-radius: 12px; padding: 20px; border: 1px solid #e9d5ff; }
.entertainment-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.ent-featured { position: relative; border-radius: 10px; overflow: hidden; }
.ent-featured img { width: 100%; aspect-ratio: 3/4; object-fit: cover; }
.ent-featured .overlay { position: absolute; bottom: 0; left: 0; right: 0; background: linear-gradient(transparent, rgba(0,0,0,0.9)); padding: 60px 16px 16px; }
.ent-featured .ent-badge { background: var(--purple); color: #fff; padding: 3px 10px; border-radius: 20px; font-size: 10px; font-weight: 700; }
.ent-featured h3 { font-size: 18px; color: #fff; margin-top: 8px; line-height: 1.3; }
.ent-featured p { font-size: 12px; color: rgba(255,255,255,0.7); margin-top: 6px; }
.ent-stack { display: flex; flex-direction: column; gap: 12px; }
.ent-card { display: flex; gap: 12px; background: #fff; border-radius: 10px; padding: 10px; box-shadow: 0 2px 8px rgba(147,51,234,0.08); border: 1px solid #e9d5ff; }
.ent-card .thumb { flex-shrink: 0; width: 80px; height: 80px; border-radius: 8px; overflow: hidden; }
.ent-card .thumb img { width: 100%; height: 100%; object-fit: cover; }
.ent-card .info { flex: 1; display: flex; flex-direction: column; justify-content: center; }
.ent-card .ent-label { font-size: 10px; color: var(--purple); font-weight: 700; text-transform: uppercase; }
.ent-card h4 { font-size: 14px; line-height: 1.3; margin-top: 4px; }
.ent-card .date { font-size: 11px; color: var(--muted); margin-top: 4px; }

/* === খেলা (Horizontal Cards) === */
.sports-section { margin-bottom: 32px; }
.sports-list { display: flex; flex-direction: column; gap: 14px; }
.sports-card { display: flex; gap: 16px; padding: 12px; background: var(--card); border: 1px solid var(--border); border-radius: 8px; transition: box-shadow 0.2s; }
.sports-card:hover { box-shadow: var(--shadow-hover); }
.sports-card.featured { background: #ecfdf5; border-left: 4px solid var(--green); }
.sports-card .thumb { flex-shrink: 0; width: 120px; height: 80px; overflow: hidden; border-radius: 6px; }
.sports-card .thumb img { width: 100%; height: 100%; object-fit: cover; }
.sports-card h4 { font-size: 15px; line-height: 1.3; }
.sports-card p { font-size: 13px; color: var(--muted); margin-top: 4px; }
.sports-card .meta { font-size: 11px; color: var(--muted); margin-top: 6px; }

/* === প্রযুক্তি (Masonry Grid) === */
.tech-section { margin-bottom: 32px; }
.tech-grid { display: grid; grid-template-columns: 2fr 1fr; gap: 16px; }
.tech-featured { overflow: hidden; border-radius: 8px; position: relative; }
.tech-featured img { width: 100%; height: 100%; min-height: 220px; object-fit: cover; }
.tech-featured .tech-badge { position: absolute; top: 12px; left: 12px; background: var(--cyan); color: #fff; padding: 4px 12px; border-radius: 4px; font-size: 11px; font-weight: 700; z-index: 2; }
.tech-featured .overlay { position: absolute; bottom: 0; left: 0; right: 0; background: linear-gradient(transparent, rgba(0,0,0,0.9)); padding: 48px 16px 16px; }
.tech-featured h3 { font-size: 18px; color: #fff; line-height: 1.3; }
.tech-featured p { font-size: 13px; color: rgba(255,255,255,0.7); margin-top: 6px; }
.tech-side { display: flex; flex-direction: column; gap: 12px; }
.tech-card { background: #f0fdfa; border: 1px solid #ccfbf1; border-radius: 8px; padding: 12px; display: flex; gap: 8px; align-items: start; }
.tech-card .thumb { flex-shrink: 0; width: 56px; height: 56px; overflow: hidden; border-radius: 6px; }
.tech-card .thumb img { width: 100%; height: 100%; object-fit: cover; }
.tech-card h4 { font-size: 13px; font-weight: 600; line-height: 1.3; }
.tech-card .date { font-size: 11px; color: var(--muted); margin-top: 4px; display: block; }

/* === সাহিত্য (Magazine) === */
.literature-section { margin-bottom: 32px; }
.literature-wrap { background: linear-gradient(135deg, #fffbeb, #fef3c7); border-radius: 10px; padding: 20px; border: 1px solid #fde68a; }
.literature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.literature-card { background: #fff; border-radius: 8px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.06); }
.literature-card img { width: 100%; aspect-ratio: 16/10; object-fit: cover; }
.literature-card .info { padding: 12px; }
.literature-card h4 { font-size: 14px; line-height: 1.35; }
.literature-card .author { font-size: 11px; color: #92400e; margin-top: 6px; font-style: italic; }

/* === রকমারি (Zigzag) === */
.rokomari-section { margin-bottom: 32px; }
.zigzag-item { display: flex; gap: 16px; padding: 12px 0; border-bottom: 1px solid var(--border); }
.zigzag-item:nth-child(even) { flex-direction: row-reverse; }
.zigzag-item .thumb { flex-shrink: 0; width: 160px; height: 100px; overflow: hidden; border-radius: 8px; }
.zigzag-item .thumb img { width: 100%; height: 100%; object-fit: cover; }
.zigzag-item .zig-label { display: inline-block; background: #fef2f2; color: var(--red); padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 700; }
.zigzag-item h4 { font-size: 15px; margin-top: 6px; line-height: 1.3; }
.zigzag-item p { font-size: 13px; color: var(--muted); margin-top: 4px; }

/* === স্বাস্থ্য (Health Cards) === */
.health-section { margin-bottom: 32px; }
.health-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.health-card { border-radius: 10px; overflow: hidden; background: #fff; border: 1px solid #dcfce7; box-shadow: 0 2px 8px rgba(0,0,0,0.04); }
.health-card .thumb { position: relative; }
.health-card .thumb img { width: 100%; aspect-ratio: 16/9; object-fit: cover; }
.health-card .health-icon { position: absolute; top: 8px; right: 8px; background: var(--health-green); color: #fff; width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; }
.health-card .info { padding: 12px; }
.health-card h4 { font-size: 14px; line-height: 1.35; }
.health-card p { font-size: 12px; color: var(--muted); margin-top: 4px; }

/* === আন্তর্জাতিক (Dark Globe) === */
.international-section { margin-bottom: 32px; }
.international-wrap { background: linear-gradient(135deg, #1e1b4b, #312e81); border-radius: 10px; padding: 20px; display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.intl-card { display: flex; gap: 14px; align-items: start; }
.intl-card .thumb { flex-shrink: 0; width: 100px; height: 80px; overflow: hidden; border-radius: 8px; border: 2px solid rgba(255,255,255,0.15); }
.intl-card .thumb img { width: 100%; height: 100%; object-fit: cover; }
.intl-card h4 { font-size: 14px; color: #fff; line-height: 1.3; }
.intl-card p { font-size: 12px; color: rgba(255,255,255,0.6); margin-top: 4px; }
.intl-card .date { font-size: 11px; color: rgba(255,255,255,0.4); margin-top: 6px; }

/* === মতামত (Opinion / Quote Style) === */
.opinion-section { margin-bottom: 32px; }
.opinion-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.opinion-card { background: #fff; border: 1px solid #fde68a; border-radius: 10px; padding: 20px; position: relative; }
.opinion-card.highlight { background: linear-gradient(135deg, #fffbeb, #fef3c7); }
.opinion-card .quote-icon { position: absolute; top: 12px; right: 14px; font-size: 28px; color: var(--opinion); opacity: 0.2; }
.opinion-card .author-info { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.opinion-card .avatar { width: 48px; height: 48px; border-radius: 50%; object-fit: cover; border: 2px solid var(--opinion); }
.opinion-card .author-name { font-size: 13px; font-weight: 700; color: #92400e; }
.opinion-card .author-role { font-size: 11px; color: var(--amber); }
.opinion-card blockquote { font-size: 15px; font-weight: 600; line-height: 1.45; color: #1c1917; font-style: italic; border-left: 3px solid var(--opinion); padding-left: 12px; margin: 0; }

/* === এডিটর পিক (Carousel) === */
.editor-pick { margin-bottom: 32px; }
.carousel-controls { display: flex; gap: 6px; }
.carousel-btn { width: 28px; height: 28px; border-radius: 4px; border: 1px solid var(--border); background: #fff; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 14px; }
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); }
.carousel-track { overflow: hidden; }
.carousel-inner { display: flex; gap: 16px; transition: transform 0.3s ease; }
.carousel-card { flex: 0 0 calc(25% - 12px); }
.carousel-card .thumb { overflow: hidden; border-radius: 6px; }
.carousel-card .thumb img { width: 100%; aspect-ratio: 4/3; object-fit: cover; }
.carousel-card .label-badge { margin-top: 8px; }
.carousel-card h3 { font-size: 14px; margin-top: 4px; line-height: 1.35; }
.carousel-card .meta { font-size: 12px; color: var(--muted); margin-top: 4px; }

/* === Sidebar === */
.sidebar .widget { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; margin-bottom: 20px; box-shadow: var(--shadow-card); }
.sidebar .widget-title { font-size: 15px; font-weight: 700; padding: 12px 16px 8px; border-bottom: 2px solid var(--primary); margin-bottom: 0; display: flex; align-items: center; gap: 6px; }
.sidebar .widget-title .dot { width: 10px; height: 10px; background: var(--primary); border-radius: 2px; }
.label-widget-list { display: flex; flex-wrap: wrap; gap: 8px; padding: 12px 16px 16px; }
.label-widget-list .label-pill { display: inline-block; background: var(--primary-light); color: var(--primary); padding: 5px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; }
.label-widget-list .label-pill:hover { background: var(--primary); color: #fff; }

/* 3-Tab Widget */
.tab-widget { background: var(--card); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
.tab-headers { display: flex; border-bottom: 2px solid var(--border); }
.tab-btn { flex: 1; padding: 10px 8px; font-size: 13px; font-weight: 500; background: #fafafa; color: var(--muted); border: none; cursor: pointer; transition: all 0.2s; font-family: inherit; border-bottom: 2px solid transparent; }
.tab-btn.active { font-weight: 700; background: var(--primary); color: #fff; border-bottom-color: var(--primary); }
.tab-content { padding: 14px; }
.tab-content[data-scroll="true"] { max-height: 400px; overflow-y: auto; }
.tab-post { display: flex; gap: 10px; padding: 8px 0; border-bottom: 1px solid #f4f4f5; }
.tab-post:last-child { border-bottom: none; }
.tab-post .thumb { flex-shrink: 0; width: 68px; height: 52px; overflow: hidden; border-radius: 6px; }
.tab-post .thumb img { width: 100%; height: 100%; object-fit: cover; }
.tab-post .num { flex-shrink: 0; width: 24px; height: 24px; border-radius: 50%; background: var(--primary-light); color: var(--primary); display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; margin-top: 2px; }
.tab-post h4 { font-size: 13px; font-weight: 600; line-height: 1.3; }
.tab-post .date { font-size: 11px; color: var(--muted); margin-top: 3px; display: block; }

/* ইতিহাসের এই দিনে (On This Day Widget) */
.onthisday-widget { background: var(--card); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.05); margin-top: 20px; }
.onthisday-header { background: linear-gradient(135deg, #1e3a5f, #2563eb); padding: 12px 16px; display: flex; align-items: center; gap: 8px; }
.onthisday-header .icon { font-size: 20px; }
.onthisday-header h3 { font-size: 14px; font-weight: 700; color: #fff; margin: 0; }
.onthisday-header .today { font-size: 11px; color: rgba(255,255,255,0.7); display: block; }
.onthisday-tabs { display: flex; border-bottom: 2px solid var(--border); }
.onthisday-tab { flex: 1; padding: 10px 8px; font-size: 13px; display: flex; align-items: center; justify-content: center; gap: 6px; font-weight: 500; background: #f8fafc; color: var(--muted); border: none; cursor: pointer; transition: all 0.2s; font-family: inherit; }
.onthisday-tab.active { font-weight: 700; background: #2563eb; color: #fff; }
.onthisday-content { max-height: 320px; overflow-y: auto; padding: 14px; }
.onthisday-event { display: flex; gap: 10px; padding: 10px 0; border-bottom: 1px solid #f4f4f5; }
.onthisday-event:last-child { border-bottom: none; }
.onthisday-year { flex-shrink: 0; min-width: 48px; height: 24px; border-radius: 12px; background: linear-gradient(135deg, #dbeafe, #bfdbfe); color: var(--blue); display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; padding: 0 8px; }
.onthisday-event p { font-size: 13px; line-height: 1.4; margin: 0; }
.onthisday-quote { padding: 12px 0; border-bottom: 1px solid #f4f4f5; }
.onthisday-quote:last-child { border-bottom: none; }
.onthisday-quote blockquote { font-size: 13px; line-height: 1.45; font-style: italic; border-left: 3px solid #2563eb; padding-left: 10px; margin: 0; }
.onthisday-quote .author { font-size: 11px; color: #2563eb; font-weight: 600; margin-top: 6px; padding-left: 14px; }
.onthisday-source { border-top: 1px solid #f4f4f5; padding: 6px 14px; text-align: right; font-size: 10px; color: #a1a1aa; }

.sidebar .compact-post { display: flex; gap: 10px; padding: 8px 16px; border-bottom: 1px solid var(--border); }
.sidebar .compact-post:last-child { border-bottom: none; }
.sidebar .compact-post .thumb { flex-shrink: 0; width: 72px; height: 56px; overflow: hidden; border-radius: 4px; }
.sidebar .compact-post .thumb img { width: 100%; height: 100%; object-fit: cover; }
.sidebar .compact-post h4 { font-size: 13px; font-weight: 600; line-height: 1.3; }
.sidebar .compact-post:hover h4 { color: var(--primary); }
.sidebar .compact-post .date { font-size: 11px; color: var(--muted); margin-top: 4px; }

/* === Main Layout === */
.main-layout { display: grid; grid-template-columns: 1fr 340px; gap: 32px; }

/* === Post Card (generic) === */
.post-card { padding-bottom: 16px; border-bottom: 1px solid var(--border); }
.post-card .thumb { overflow: hidden; border-radius: var(--radius); }
.post-card .thumb img { width: 100%; aspect-ratio: 16/10; object-fit: cover; transition: transform 0.3s; }
.post-card:hover .thumb img { transform: scale(1.02); }
.post-card h3 { font-size: 15px; margin-top: 8px; line-height: 1.35; transition: color 0.2s; }
.post-card:hover h3 { color: var(--primary); }
.post-card .excerpt { font-size: 13px; color: var(--muted); margin-top: 4px; }
.post-card .meta { font-size: 12px; color: var(--muted); margin-top: 8px; }
.posts-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* === Post Page === */
.post-page { max-width: 800px; margin: 0 auto; padding: 24px 1rem; }
.post-page .post-title { font-size: 1.75rem; margin-bottom: 12px; line-height: 1.3; }
.post-page .post-meta { font-size: 13px; color: var(--muted); margin-bottom: 16px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.post-page .post-image { width: 100%; border-radius: var(--radius); margin-bottom: 20px; }
.post-page .post-body { font-size: 16px; line-height: 1.8; }
.post-page .post-body p { margin-bottom: 16px; }
.post-page .post-body img { border-radius: var(--radius); margin: 16px 0; }
.post-page .post-body h2, .post-page .post-body h3 { margin-top: 24px; margin-bottom: 12px; }
.post-page .post-labels { margin-top: 20px; display: flex; gap: 8px; flex-wrap: wrap; }

/* === Comments === */
.comments-section { margin-top: 32px; padding-top: 20px; border-top: 1px solid var(--border); }

/* === Footer === */
.site-footer { background: var(--foreground); margin-top: 32px; padding: 32px 0 16px; }
.footer-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.site-footer h3 { font-size: 1.15rem; color: #fff; margin-bottom: 8px; }
.site-footer h3 .accent { color: var(--primary); }
.site-footer h4 { font-size: 14px; font-weight: 700; color: #fff; margin-bottom: 12px; }
.site-footer p, .site-footer a, .site-footer li { font-size: 13px; color: rgba(255,255,255,0.6); }
.site-footer a:hover { color: var(--primary); }
.site-footer ul { list-style: none; columns: 2; }
.site-footer ul li { padding: 3px 0; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); margin-top: 24px; padding-top: 16px; text-align: center; }
.footer-bottom p { font-size: 12px; color: rgba(255,255,255,0.4); }

/* === Pagination === */
.blog-pager { display: flex; justify-content: center; gap: 12px; padding: 24px 0; }
.blog-pager a { display: inline-block; padding: 8px 20px; background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); font-size: 13px; font-weight: 600; color: var(--foreground); transition: all 0.2s; }
.blog-pager a:hover { border-color: var(--primary); color: var(--primary); }

/* === Responsive === */
@media (max-width: 1024px) {
  .main-layout { grid-template-columns: 1fr; }
  .sidebar { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
}

@media (max-width: 768px) {
  .top-news-grid, .national-grid { grid-template-columns: 1fr; }
  .top-news-side { grid-template-columns: 1fr 1fr; }
  .entertainment-grid { grid-template-columns: 1fr; }
  .tech-grid { grid-template-columns: 1fr; }
  .international-wrap { grid-template-columns: 1fr; }
  .opinion-grid { grid-template-columns: 1fr; }
  .literature-grid { grid-template-columns: 1fr; }
  .health-grid { grid-template-columns: 1fr; }
  .posts-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 24px; }
  .sidebar { grid-template-columns: 1fr; }
  .carousel-card { flex: 0 0 calc(50% - 8px); }
  .zigzag-item, .zigzag-item:nth-child(even) { flex-direction: column; }
  .zigzag-item .thumb { width: 100%; height: auto; }
  .nav-list { display: none; flex-direction: column; position: absolute; top: 100%; left: 0; right: 0; background: var(--card); border-bottom: 1px solid var(--border); z-index: 50; }
  .nav-list.open { display: flex; }
  .mobile-menu-btn { display: block; }
  .site-title { font-size: 1.5rem; }
  .post-page .post-title { font-size: 1.35rem; }
}

/* === Utility === */
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border-width: 0; }

/* === Animation === */
@keyframes slideUp { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
.news-entrance { animation: slideUp 0.4s cubic-bezier(0.4,0,0.2,1) both; }

/* Hide Blogger defaults */
.blog-feeds, .feed-links { display: none; }

b:includable.script:
//
(function(){
  var months=['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
  var days=['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'];
  var d=new Date();
  function toBn(n){return String(n).replace(/[0-9]/g,function(m){return '০১২৩৪৫৬৭৮৯'[m]});}
  document.getElementById('current-date').textContent=toBn(d.getDate())+' '+months[d.getMonth()]+', '+toBn(d.getFullYear())+' | '+days[d.getDay()];
})();
