body.script:
//
(function(){
  var BLOG_URL = (window.location.origin || (window.location.protocol + '//' + window.location.host)).replace(/\/$/, '');

  var LABEL_ALIASES = {
    'জাতীয়': ['জাতীয়', 'সারাদেশ', 'দেশ'],
    'আন্তর্জাতিক': ['আন্তর্জাতিক', 'বিশ্ব'],
    'এডিটর পিক': ['এডিটর পিক', 'সম্পাদকীয়', 'সম্পাদকীয়', 'Editor Pick'],
    'আলোচিত': ['আলোচিত', 'ট্রেন্ডিং', 'Trending'],
    'স্বাস্থ্য': ['স্বাস্থ্য', 'লাইফস্টাইল'],
    'রকমারি': ['রকমারি', 'ফিচার'],
    'মতামত': ['মতামত', 'Opinion']
  };

  // Helper: fetch posts by label via Blogger JSON feed (with alias + timeout fallback)
  function fetchLabel(label, count, callback) {
    var candidates = LABEL_ALIASES[label] || [label];
    var idx = 0;

    function parsePosts(data) {
      var posts = [];
      if (data.feed && data.feed.entry) {
        data.feed.entry.forEach(function(e) {
          var link = '';
          e.link.forEach(function(l) { if (l.rel === 'alternate') link = l.href; });
          var img = '';
          if (e.media$thumbnail) img = e.media$thumbnail.url.replace(/s72-c/, 's600-c');
          var labels = [];
          if (e.category) e.category.forEach(function(c) { labels.push(c.term); });
          posts.push({
            title: e.title.$t,
            url: link,
            image: img,
            excerpt: e.summary ? e.summary.$t.substring(0, 100) : '',
            author: e.author[0].name.$t,
            date: e.published.$t.substring(0, 10),
            labels: labels
          });
        });
      }
      return posts;
    }

    function tryNext() {
      if (idx >= candidates.length) {
        callback([]);
        return;
      }

      var currentLabel = candidates[idx++];
      var url = BLOG_URL + '/feeds/posts/default/-/' + encodeURIComponent(currentLabel) + '?alt=json&max-results=' + count;
      var s = document.createElement('script');
      var cbName = 'cb_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
      var done = false;

      function cleanup() {
        if (done) return;
        done = true;
        try { delete window[cbName]; } catch (e) { window[cbName] = undefined; }
        if (s.parentNode) s.parentNode.removeChild(s);
      }

      var timer = setTimeout(function() {
        cleanup();
        tryNext();
      }, 8000);

      window[cbName] = function(data) {
        clearTimeout(timer);
        var posts = parsePosts(data || {});
        cleanup();
        if (posts.length) callback(posts);
        else tryNext();
      };

      s.onerror = function() {
        clearTimeout(timer);
        cleanup();
        tryNext();
      };

      s.src = url + '&callback=' + cbName;
      document.body.appendChild(s);
    }

    tryNext();
  }

  // Helper: get visible label (skip শীর্ষ সংবাদ)
  function getVisibleLabel(labels) {
    for (var i = 0; i < labels.length; i++) {
      if (labels[i] !== 'শীর্ষ সংবাদ') return labels[i];
    }
    return labels[0] || '';
  }

  // === TICKER ===
  fetchLabel('শীর্ষ সংবাদ', 10, function(posts) {
    if (posts.length === 0) {
      // fallback: fetch recent
      fetchLabel('জাতীয়', 6, function(p2) { buildTicker(p2); });
    } else {
      buildTicker(posts);
    }
  });
  function buildTicker(posts) {
    var html = '';
    posts.forEach(function(p) { html += '<a href="' + p.url + '">' + p.title + '</a>'; });
    document.getElementById('ticker-inner').innerHTML = html + html;
  }

  // === রাজনীতি (Parliament/Debate Style) ===
  fetchLabel('রাজনীতি', 5, function(posts) {
    if (!posts.length) return;
    var el = document.getElementById('sec-politics');
    var html = '<div class="section-header politics"><div class="left"><span class="dot"></span><h2>রাজনীতি</h2></div><a class="more-link" href="' + BLOG_URL + '/search/label/রাজনীতি">আরো ❯</a></div>';
    html += '<div class="politics-wrap"><div class="politics-grid">';
    // Featured card
    html += '<div class="politics-featured"><a href="' + posts[0].url + '">';
    html += '<div class="thumb">';
    if (posts[0].image) html += '<img src="' + posts[0].image + '" alt=""/>';
    html += '<div class="thumb-overlay"><span class="pol-badge">🏛️ রাজনীতি</span></div></div>';
    html += '<div class="info"><h3>' + posts[0].title + '</h3><p>' + posts[0].excerpt + '</p>';
    html += '<div class="author-row"><span class="author-avatar">প</span><span class="author-name">' + posts[0].author + '</span><span style="font-size:11px;color:#a1a1aa">· ' + posts[0].date + '</span></div>';
    html += '</div></a></div>';
    // Numbered list
    html += '<div class="politics-list">';
    for (var i = 1; i < posts.length; i++) {
      html += '<a href="' + posts[i].url + '" class="politics-item">';
      html += '<span class="num">' + i + '</span>';
      html += '<div><h4>' + posts[i].title + '</h4>';
      html += '<div class="meta"><span class="author">' + posts[i].author + '</span><span class="date">' + posts[i].date + '</span></div>';
      html += '</div></a>';
    }
    html += '</div></div></div>';
    el.innerHTML = html;
  });

  // === আলোচিত (Trending/Viral Style) ===
  fetchLabel('আলোচিত', 5, function(posts) {
    if (!posts.length) return;
    var el = document.getElementById('sec-trending');
    var html = '<div class="trending-header"><div class="left"><span class="fire">🔥</span><h2>আলোচিত</h2><span class="trending-badge">TRENDING</span></div>';
    html += '<a class="more-link" style="color:#ea580c;font-size:13px;font-weight:600" href="' + BLOG_URL + '/search/label/আলোচিত">আরো ❯</a></div>';
    html += '<div class="trending-grid">';
    // Big featured
    html += '<div class="trending-featured"><a href="' + posts[0].url + '">';
    if (posts[0].image) html += '<img src="' + posts[0].image + '" alt=""/>';
    html += '<div class="overlay"></div>';
    html += '<div class="badges"><span class="t-badge">🔥 আলোচিত</span><span class="view-badge">👁 ১২.৫K</span></div>';
    html += '<div class="content"><h3>' + posts[0].title + '</h3><p>' + posts[0].excerpt + '</p></div>';
    html += '</a></div>';
    // Side cards
    html += '<div class="trending-side">';
    for (var i = 1; i < posts.length; i++) {
      html += '<a href="' + posts[i].url + '" class="trending-card"><div class="inner">';
      html += '<div class="thumb">';
      if (posts[i].image) html += '<img src="' + posts[i].image + '" alt=""/>';
      html += '<span class="rank">' + i + '</span></div>';
      html += '<div><h4>' + posts[i].title + '</h4>';
      html += '<div class="fire-date"><span class="fire">🔥</span><span>' + posts[i].date + '</span></div>';
      html += '</div></div></a>';
    }
    html += '</div></div>';
    el.innerHTML = html;
  });

  // === জাতীয় (Timeline) ===
  fetchLabel('জাতীয়', 5, function(posts) {
    if (!posts.length) return;
    var el = document.getElementById('sec-national');
    var html = '<div class="section-header blue"><div class="left"><span class="dot"></span><h2>জাতীয়</h2></div><a class="more-link" href="' + BLOG_URL + '/search/label/জাতীয়">আরো ❯</a></div>';
    html += '<div class="national-grid">';
    // Featured
    html += '<div class="national-featured"><a href="' + posts[0].url + '">';
    if (posts[0].image) html += '<img src="' + posts[0].image + '" alt=""/>';
    html += '<div class="info"><span class="label-badge" style="background:#1d4ed8;color:#fff;border-radius:4px;padding:3px 10px">' + getVisibleLabel(posts[0].labels) + '</span>';
    html += '<h3>' + posts[0].title + '</h3><p>' + posts[0].excerpt + '</p></div></a></div>';
    // Timeline
    html += '<div class="timeline-list">';
