  var carouselIdx = 0;
  window.moveCarousel = function(dir) {
    var inner = document.getElementById('carousel-inner');
    if (!inner) return;
    var cards = inner.children.length;
    var visible = window.innerWidth < 768 ? 2 : 4;
    var maxIdx = Math.max(0, cards - visible);
    carouselIdx = Math.max(0, Math.min(maxIdx, carouselIdx + dir));
    var pct = carouselIdx * (100 / visible + 1.5);
    inner.style.transform = 'translateX(-' + pct + '%)';
  };

