    html += '<div class="info"><span class="label-badge" style="background:var(--amber);color:#fff;border-radius:4px;padding:3px 10px">' + getVisibleLabel(posts[0].labels) + '</span>';
    html += '<h3>' + posts[0].title + '</h3><p>' + posts[0].excerpt + '</p></div></a></div>';
