      html += '<a href="' + posts[i].url + '" class="timeline-item">';
      html += '<div class="timeline-dot-wrap"><div class="timeline-dot" style="background:var(--amber);border-color:#fef3c7"></div>';
      if (i < posts.length - 1) html += '<div class="timeline-line" style="background:#fef3c7"></div>';
      html += '</div><div><h4>' + posts[i].title + '</h4><span class="date">' + posts[i].date + '</span></div></a>';
    }
    html += '</div></div>';
    el.innerHTML = html;
  });

  var tabData = { popular: [], sports: [], latest: [] };
  var tabLoaded = 0;
  function checkTabsReady() {
    tabLoaded++;
    if (tabLoaded >= 3) buildTabs();
  }
  fetchLabel('জাতীয়', 5, function(posts) { tabData.popular = posts; checkTabsReady(); });
  fetchLabel('খেলা', 5, function(posts) { tabData.sports = posts; checkTabsReady(); });
  // Latest - fetch from default feed
  (function() {
    var url = BLOG_URL + '/feeds/posts/default?alt=json&max-results=8&callback=latestCb';
    var s = document.createElement('script');
    window.latestCb = function(data) {
      var posts = [];
      if (data.feed && data.feed.entry) {
        data.feed.entry.forEach(function(e) {
          var link = '';
          e.link.forEach(function(l) { if (l.rel === 'alternate') link = l.href; });
          posts.push({ title: e.title.$t, url: link, date: e.published.$t.substring(0, 10) });
        });
      }
      tabData.latest = posts;
      checkTabsReady();
      delete window.latestCb;
      s.remove();
    };
    document.body.appendChild(s);
    s.src = url;
  })();

  function buildTabs() {
    var el = document.getElementById('sidebar-tabs');
    if (!el) return;
    var html = '<div class="tab-headers">';
    html += '<button class="tab-btn active" onclick="switchTab(0,this)">🔥 জনপ্রিয়</button>';
    html += '<button class="tab-btn" onclick="switchTab(1,this)">⚽ খেলা</button>';
    html += '<button class="tab-btn" onclick="switchTab(2,this)">🕐 সর্বশেষ</button>';
    html += '</div>';

    // Tab 0: Popular
    html += '<div class="tab-content tab-panel" data-tab="0">';
    tabData.popular.forEach(function(p) {
      html += '<a href="' + p.url + '" class="tab-post">';
      if (p.image) html += '<div class="thumb"><img src="' + p.image + '" alt=""/></div>';
      html += '<div><h4>' + p.title + '</h4><span class="date">' + p.date + '</span></div></a>';
    });
    html += '</div>';

    // Tab 1: Sports
    html += '<div class="tab-content tab-panel" data-tab="1" style="display:none">';
    tabData.sports.forEach(function(p) {
      html += '<a href="' + p.url + '" class="tab-post">';
      if (p.image) html += '<div class="thumb"><img src="' + p.image + '" alt=""/></div>';
      html += '<div><h4>' + p.title + '</h4><span class="date">' + p.date + '</span></div></a>';
    });
    html += '</div>';

    // Tab 2: Latest (scrollable)
    html += '<div class="tab-content tab-panel" data-tab="2" data-scroll="true" style="display:none">';
    tabData.latest.forEach(function(p, i) {
      html += '<a href="' + p.url + '" class="tab-post">';
      html += '<span class="num">' + (i + 1) + '</span>';
      html += '<div><h4>' + p.title + '</h4><span class="date">' + p.date + '</span></div></a>';
    });
    html += '</div>';

    el.innerHTML = html;
  }

  window.switchTab = function(idx, btn) {
    var widget = btn.closest('.tab-widget');
    widget.querySelectorAll('.tab-btn').forEach(function(b) { b.classList.remove('active'); });
    btn.classList.add('active');
    widget.querySelectorAll('.tab-panel').forEach(function(p) { p.style.display = 'none'; });
    widget.querySelector('[data-tab="' + idx + '"]').style.display = '';
  };

  // === ইতিহাসের এই দিনে (Wikipedia On This Day) ===
  (function() {
    var today = new Date();
    var month = String(today.getMonth() + 1).padStart(2, '0');
    var day = String(today.getDate()).padStart(2, '0');
    var el = document.getElementById('onthisday-widget');
    if (!el) return;

    // Bangla date
    function toBn(n) { return String(n).replace(/[0-9]/g, function(m) { return '০১২৩৪৫৬৭৮৯'[m]; }); }
    var bnMonths = ['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
    var todayStr = toBn(today.getDate()) + ' ' + bnMonths[today.getMonth()];

    // Header
    var html = '<div class="onthisday-header"><span class="icon">📜</span><div><h3>ইতিহাসের এই দিনে</h3><span class="today">' + todayStr + '</span></div></div>';
    html += '<div class="onthisday-tabs">';
    html += '<button class="onthisday-tab active" onclick="switchOTD(0,this)"><i class="fas fa-calendar-alt"></i> ঘটনাবলি</button>';
    html += '<button class="onthisday-tab" onclick="switchOTD(1,this)"><i class="fas fa-comment-dots"></i> উক্তি</button>';
    html += '</div>';
    html += '<div class="onthisday-content otd-panel" data-otd="0" id="otd-events">লোড হচ্ছে...</div>';
    html += '<div class="onthisday-content otd-panel" data-otd="1" id="otd-quotes" style="display:none">লোড হচ্ছে...</div>';
    html += '<div class="onthisday-source">উৎস: উইকিপিডিয়া</div>';
    el.innerHTML = html;

    // Fetch from Wikipedia
    fetch('https://api.wikimedia.org/feed/v1/wikipedia/bn/onthisday/all/' + month + '/' + day, {
      headers: { 'Accept': 'application/json' }
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
      // Events
      var events = (data.events || data.selected || []).slice(0, 15);
      var evHTML = '';
      events.forEach(function(e) {
        evHTML += '<div class="onthisday-event">';
        evHTML += '<span class="onthisday-year">' + (e.year ? toBn(Math.abs(e.year)) : '') + '</span>';
        evHTML += '<p>' + (e.text || '') + '</p></div>';
      });
      if (!evHTML) evHTML = '<p style="color:var(--muted);font-size:13px">আজকের জন্য কোনো ঘটনা পাওয়া যায়নি।</p>';
      document.getElementById('otd-events').innerHTML = evHTML;

      // Births as quotes
      var births = (data.births || []).slice(0, 10);
      var qHTML = '';
      births.forEach(function(b) {
        var name = b.pages && b.pages[0] ? b.pages[0].normalizedtitle || b.pages[0].title : 'অজানা';
        qHTML += '<div class="onthisday-quote"><blockquote>"' + (b.text || '') + '"</blockquote>';
        qHTML += '<div class="author">— ' + name + '</div></div>';
      });
      if (!qHTML) qHTML = '<p style="color:var(--muted);font-size:13px">আজকের জন্য কোনো উক্তি পাওয়া যায়নি।</p>';
      document.getElementById('otd-quotes').innerHTML = qHTML;
    })
    .catch(function() {
      document.getElementById('otd-events').innerHTML = '<p style="color:var(--muted);font-size:13px">ডাটা লোড করা যায়নি।</p>';
      document.getElementById('otd-quotes').innerHTML = '<p style="color:var(--muted);font-size:13px">ডাটা লোড করা যায়নি।</p>';
    });
  })();

  window.switchOTD = function(idx, btn) {
    var widget = btn.closest('.onthisday-widget');
    widget.querySelectorAll('.onthisday-tab').forEach(function(b) { b.classList.remove('active'); });
    btn.classList.add('active');
    widget.querySelectorAll('.otd-panel').forEach(function(p) { p.style.display = 'none'; });
    widget.querySelector('[data-otd="' + idx + '"]').style.display = '';
  };

})();
//
